import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·26","description":"易小帖 - 卷二·26","frontmatter":{"title":"卷二·26","description":"易小帖 - 卷二·26"},"headers":[],"relativePath":"zh/classics/yixiaotie/066.md","filePath":"zh/classics/yixiaotie/066.md"}'),o={name:"zh/classics/yixiaotie/066.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·26",tabindex:"-1"},[r("卷二·26 "),e("a",{class:"header-anchor",href:"#卷二·26","aria-label":"Permalink to “卷二·26”"},"​")],-1),e("p",null,"乾寶註三易謂：連山首艮，歸藏首坤，周易首乾。然又雲：「天地定位，山澤通氣，雷風相薄，水火不相射」，此小成之易也。「帝出乎震，齊乎巽，相見乎離，致役乎坤，說言乎兌，戰乎乾，勞乎坎。成言乎艮」，此連山之易也。初乾初（即坤）初艮初兌初犖（即坎）初離初釐（即震）初巽，此歸藏之易也。則連山終艮，歸藏次坤，與首艮首坤之說自相牴牾。且以《大傳》帝出乎震一節為歸藏之易，亦不合，且亦不知所據。若又雲伏羲之易小成為先天，神農之易中成為中天，黃帝之易大成為後天，此即宋儒以伏羲為先天，以文王為後天，以八卦為小成，以六十四卦為大成之所始。夫《大傳》祗有「八卦而小成」一語，此又增中成、大成，原是不妥。且其雲小成者，就揲蓍者言之，謂十八變中九變而成內卦，祗為小成，必十八變而後引伸觸類，能事已畢。非謂伏羲祗畫八卦，至神農而後重之。如京房所雲：神農重乎八純。《史記》所雲神農觀日中交易而作重卦也*。八卦因重，皆伏羲事，與神農無與，《大傳》自明其以小成屬羲易，固已可怪。若宋人造為因重之法，陰陽太少，層累加畫，指為先天，而以先天屬伏羲，乃取《說卦》中夫子所傳羲易卦位，攧撲不破者指為後天，反以為此文王易非羲易，則悖誕極矣。小成大成，先天后天，太陽太陰，少陽少陰，皆前人已言，而更易其說，遂致懸絶，始知偶然之言，後將憑倚，不可不慎也。又《大傳》有「上古結繩而治」、「作易者其於中古」語，後儒遂增入下古，以為伏羲上古，文王中古，孔子下古。易之影嚮可笑，類如此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
